// Some portions generated by Codex
'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const {workbenchScriptPath}=require('./workbench-scripts.js');

function api() {
    const values=new Map();
    const storage={getItem:key=>values.get(key)||null,setItem:(key,value)=>values.set(key,value)};
    const sandbox={console,localStorage:storage,window:{},setTimeout,clearTimeout};
    vm.createContext(sandbox);
    for(const file of ['graphAdditions.js','queryStream.js'])
        vm.runInContext(fs.readFileSync(workbenchScriptPath(file),'utf8'),sandbox,{filename:file});
    return {stream:sandbox.workbench.queryStream,additions:sandbox.workbench.graphAdditions,storage};
}

test('classic queue accepts canonical Unicode-escaped fixed references and rejects broken escapes',()=>{
    const {additions,storage}=api();
    const context={basePath:'/wb',repositoryId:'r',serverIdentity:'server'};
    assert.equal(additions.add(context,{kind:'resource',term:'<_:a\\u0020b\\u005Cu0041>'},storage),1);
    assert.equal(additions.add(context,{kind:'resource',term:'<_:x\\q>'},storage),0);
    assert.equal(additions.add(context,{kind:'resource',term:'<_:>'},storage),2);
});

test('classic result actions authorize certified blank terms and keep raw labels display-only',()=>{
    const {stream,additions,storage}=api();
    const context={basePath:'/wb',repositoryId:'r',serverIdentity:'server'};
    for(const raw of ['','_:alice','a b>\\u0041','🙂']) {
        assert.equal(stream.addResourceToGraph(context,{kind:'bnode',value:raw,reference:true}),true);
    }
    assert.equal(stream.addResourceToGraph(context,{kind:'bnode',value:'alice',scope:'document'}),false);
    assert.equal(stream.formatRdfTerm({kind:'bnode',value:'alice',scope:'document'},{}).exploreHref,undefined);
    assert.equal(stream.formatRdfTerm({kind:'bnode',value:'alice',reference:true},{}).exploreHref,'explore?resource=%3C_%3Aalice%3E');
    const queued=JSON.parse(JSON.stringify(additions.pending(context,storage)));
    assert.deepEqual(queued.map(e=>e.term),['<_:>','<_:_:alice>','<_:a\\u0020b\\u003E\\u005Cu0041>','<_:🙂>']);
});

test('compact certified blank terms survive framing and recursive unpacking',()=>{
    const {stream}=api();
    const records=[];
    const state=new stream.QueryResultState();
    const parser=new stream.NdjsonResultParser(record=>{state.accept(record);records.push(record);});
    for(const record of [
        {type:'head',version:2,'term-encoding':'array'},
        {type:'view',id:'tuple'},
        {type:'vars',values:['source']},
        {type:'rows',values:[[[1,'alice',null,true]]]},
        {type:'end',count:1},
    ]) parser.push(JSON.stringify(record)+'\n');
    parser.finish();
    assert.equal(stream.addResourceToGraph({basePath:'/wb',repositoryId:'r',serverIdentity:'server'},records[3].values[0][0]),true);
});

test('nested triple displays do not grant Explore authority to any untrusted component',()=>{
    const {stream}=api();
    const predicate={kind:'iri',value:'urn:p'};
    const untrusted={kind:'triple',subject:{kind:'iri',value:'urn:s'},predicate,
        object:{kind:'triple',subject:{kind:'bnode',value:'remote',scope:'doc'},predicate,object:{kind:'literal',value:'x'}}};
    assert.equal(stream.formatRdfTerm(untrusted,{}).exploreHref,undefined);
});
